import { root } from "./vars";
import { sounds } from "./data";
import { renderTitle, renderSoundsContainer, renderButton, renderVolume, changeVolumeHandle, } from "./components";
import { playSound, pauseSound, stopSound } from "./utils";
import pauseIcon from "./images/icons/pause.svg";
import "./index.scss";
var isPlaying = false;
var soundIdPlayed = 0;
var soundPlayed = "";
var soundPlayedIcon = "";
function onSoundClickHandler(evt) {
    var button = evt.target;
    soundPlayed = button.children[0];
    soundPlayedIcon = button.children[1].currentSrc;
    document.body.className = button.className;
    if (isPlaying && soundIdPlayed === Number(button.id)) {
        pauseSound(soundPlayed, container, soundIdPlayed);
        isPlaying = false;
        return;
    }
    if (isPlaying && soundIdPlayed !== Number(button.id)) {
        var currentSound = document.getElementById(soundIdPlayed).children[0];
        stopSound(currentSound, sounds, soundIdPlayed, soundPlayed);
        soundIdPlayed = Number(button.id);
        playSound(soundPlayed, container, pauseIcon, soundIdPlayed);
        isPlaying = true;
        return;
    }
    soundIdPlayed = Number(button.id);
    playSound(soundPlayed, container, pauseIcon, soundIdPlayed);
    isPlaying = true;
}
var title = renderTitle();
root.append(title);
var container = renderSoundsContainer();
root.append(container);
sounds.forEach(function (sound) { return container.append(renderButton(sound)); });
var volume = renderVolume();
root.append(volume);
container.addEventListener("click", onSoundClickHandler);
volume.addEventListener("input", function () { return changeVolumeHandle(soundPlayed, volume); });
